/**
 * Wire types of the `/v1` API. Shapes come from the server's OpenAPI document (`schema.ts`,
 * regenerated by `pnpm --filter web gen:api`); this file only names them and adds what the
 * document does not carry (the `Api` surface, query shapes, `/v1/doctor`).
 */
import type { components, paths } from './schema.js';

type Schemas = components['schemas'];
type Json200<Op> = Op extends { responses: { 200: { content: { 'application/json': infer R } } } }
  ? R
  : never;

export type Agent = Schemas['Agent'];
export type Settings = Json200<paths['/v1/settings']['get']>;
export type JudgeTransport = Settings['judge.transport'];
export type BudgetMode = Settings['budget.mode'];
export type Source = Schemas['Source'];
export type SourceStatus = Source['status'];
export type S3Remote = NonNullable<Schemas['S3Remote']>;
export type AddSourceBody = { agent: Agent; path: string } | { agent: Agent; s3: S3Remote };
export type DetectedSource = Schemas['DetectedSource'];
export type SkillRepo = Schemas['SkillRepo'];
export type DetectedSkillRepo = Schemas['DetectedSkillRepo'];
export type Job = Schemas['Job'];
export type JobStatus = Job['status'];
export type JudgeTestResult = Json200<paths['/v1/judge/test']['post']>;
export type TrendSummary = Schemas['TrendSummary'];
export type RubricRate = TrendSummary['rubrics'][number];
export type Person = Schemas['Person'];
export type PersonWithSessions = Schemas['PersonWithSessions'];
export type SessionSummary = Schemas['SessionSummary'];
export type SessionGrade = SessionSummary['grades'][number];

export type GradeDetail = Schemas['GradeDetail'];
export type SessionDetail = Schemas['SessionDetail'];
export type RubricSummary = Schemas['RubricSummary'];
export type RubricDetail = Schemas['RubricDetail'];
export type CalibrationRow = Schemas['CalibrationRow'];
export type DryRunVerdict = Schemas['DryRunVerdict'];
export type DryRunResult = Schemas['DryRunResult'];
export type Budget = Schemas['Budget'];
/** The draft body is sent along, so a dry-run tests unsaved edits. */
export type DryRunInput = NonNullable<
  paths['/v1/rubrics/{name}/dry-run']['post']['requestBody']
>['content']['application/json'] & { sessionIds: string[] };
export interface LabelInput {
  sessionId: string;
  passed: boolean;
  score?: number | undefined;
  note: string;
}
export type TraceEvent = Schemas['TraceEvent'];
export type EventKind = TraceEvent['kind'];
export type SessionResultFilter = NonNullable<
  paths['/v1/sessions']['get']['parameters']['query']
>['result'] &
  string;

export type Doctor = Schemas['DoctorReport'];
export type DoctorCheck = Doctor['checks'][number];

export interface SessionQuery {
  q?: string | undefined;
  agent?: Agent | undefined;
  /** A person's id: only that person's sessions. */
  person?: string | undefined;
  result?: SessionResultFilter | undefined;
  /** ISO instant: only sessions that started at or after it. */
  since?: string | undefined;
  cursor?: string | undefined;
  limit?: number | undefined;
}

export interface Page<T> {
  items: T[];
  nextCursor: string | null;
}

export type EventFilter = 'all' | 'errors' | 'evidence';

export interface EventQuery {
  filter: EventFilter;
  cursor?: string | undefined;
  limit?: number | undefined;
}

export type Proposal = Schemas['Proposal'];
export type ProposalStatus = Proposal['status'];
export type ProposalList = Schemas['ProposalList'];
export type ImproverRun = Schemas['ImproverRun'];
export type ImproverSchedule = Json200<paths['/v1/improver/schedule']['get']>;

export type Trends = Json200<paths['/v1/trends']['get']>;
export type TrendMarker = Trends['markers'][number];
export type TrendMarkerKind = TrendMarker['kind'];
export type TrendChange = Schemas['TrendChange'];
export type ChangeVerdict = TrendChange['verdict'];
export type TrendBucketSize = 'week' | 'day';
export type ReferenceSet = Schemas['ReferenceSet'];
export interface TrendQuery {
  /** Range in weeks (4, 12 or 26); the server turns it into from/to. */
  weeks: number;
  bucket: TrendBucketSize;
}

/** The API surface the SPA uses. `client.ts` implements it over HTTP, `mock.ts` over fixtures. */
export interface Api {
  getSettings(): Promise<Settings>;
  patchSettings(patch: Partial<Omit<Settings, 'judge.api_key_set'>>): Promise<Settings>;
  putJudgeKey(apiKey: string): Promise<void>;
  testJudge(body: { transport: JudgeTransport; apiKey?: string }): Promise<JudgeTestResult>;
  listSources(): Promise<Source[]>;
  detectSources(): Promise<DetectedSource[]>;
  addSource(body: AddSourceBody): Promise<Source>;
  listSkillRepos(): Promise<SkillRepo[]>;
  detectSkillRepos(): Promise<DetectedSkillRepo[]>;
  putGlobalSkillRepo(path: string): Promise<SkillRepo>;
  initGlobalSkillRepo(path: string): Promise<SkillRepo>;
  copyStarterRubrics(): Promise<{ copied: string[] }>;
  patchSkillRepo(
    id: string,
    body: {
      enabled?: boolean;
      acceptMode?: SkillRepo['acceptMode'];
      allowExecutable?: boolean;
    },
  ): Promise<SkillRepo>;
  startImport(): Promise<Job>;
  getJob(id: string): Promise<Job>;
  /** `days` 0 means all time. */
  getTrendSummary(days: number): Promise<TrendSummary>;
  getTrends(query: TrendQuery): Promise<Trends>;
  listTrendChanges(): Promise<TrendChange[]>;
  startReferenceRegrade(): Promise<Job>;
  getReferenceSet(): Promise<ReferenceSet>;
  addToReferenceSet(sessionId: string): Promise<void>;
  removeFromReferenceSet(sessionId: string): Promise<void>;
  listSessions(query: SessionQuery): Promise<Page<SessionSummary>>;
  listPeople(): Promise<PersonWithSessions[]>;
  getSession(id: string): Promise<SessionDetail>;
  listEvents(id: string, query: EventQuery): Promise<Page<TraceEvent> & { total: number }>;
  exchangeToken(token: string): Promise<void>;
  getDoctor(): Promise<Doctor>;
  regradeSession(id: string): Promise<Job>;
  gradeBatch(sessionIds: string[]): Promise<Job>;
  listRubrics(): Promise<RubricSummary[]>;
  getRubric(name: string): Promise<RubricDetail>;
  putRubric(
    name: string,
    body: { body: string; passThreshold: number; message: string },
  ): Promise<RubricDetail>;
  dryRunRubric(name: string, body: DryRunInput): Promise<DryRunResult>;
  addLabel(name: string, label: LabelInput): Promise<void>;
  getBudget(): Promise<Budget>;
  listProposals(status?: ProposalStatus): Promise<ProposalList>;
  getProposal(id: string): Promise<Proposal>;
  patchProposal(id: string, diff: string): Promise<Proposal>;
  acceptProposal(id: string): Promise<Proposal>;
  rejectProposal(id: string, reason: string): Promise<Proposal>;
  startImprover(since?: string): Promise<Job>;
  listImproverRuns(): Promise<ImproverRun[]>;
  getImproverSchedule(): Promise<ImproverSchedule>;
  addProjectRepo(path: string): Promise<SkillRepo>;
}
